import {WORLD} from './physics.mjs';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const stops=[[-20000,[1,2,7]],[-10000,[3,7,17]],[-4000,[4,15,32]],[-300,[6,23,46]],[400,[13,36,66]],[692,[14,30,48]]];
export function skyColor(y){if(y<=stops[0][0])return stops[0][1];for(let i=1;i<stops.length;i++)if(y<=stops[i][0]){let [a,ca]=stops[i-1],[b,cb]=stops[i],t=(y-a)/(b-a);return ca.map((v,j)=>Math.round(v+(cb[j]-v)*t));}return stops.at(-1)[1];}
export function prepareBackdrop(image,makeCanvas=(w,h)=>new OffscreenCanvas(w,h)){const c=makeCanvas(image.width,image.height),x=c.getContext('2d');x.drawImage(image,0,0);x.globalCompositeOperation='destination-in';let g=x.createLinearGradient(0,0,0,c.height);g.addColorStop(0,'#0000');g.addColorStop(.48,'#000');g.addColorStop(.87,'#000');g.addColorStop(1,'#0000');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);g=x.createLinearGradient(0,0,c.width,0);g.addColorStop(0,'#0000');g.addColorStop(.12,'#000');g.addColorStop(.88,'#000');g.addColorStop(1,'#0000');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.globalCompositeOperation='source-over';return c;}
function rand(x,y,k=0){let v=Math.sin(x*127.1+y*311.7+k*74.7)*43758.5453;return v-Math.floor(v);}
export function drawEnvironment(c,{background,camera,width,height,time}){const z=camera.zoom??1,g=c.createLinearGradient(0,0,0,height);for(let i=0;i<=20;i++){let y=height*i/20;g.addColorStop(i/20,`rgb(${skyColor(camera.y+y/z).join(',')})`);}c.fillStyle=g;c.fillRect(0,0,width,height);
const starX=camera.x*.12,starY=camera.y*.22,cell=190;for(let iy=Math.floor(starY/cell)-1;iy<=Math.ceil((starY+height)/cell);iy++)for(let ix=Math.floor(starX/cell)-1;ix<=Math.ceil((starX+width)/cell);ix++)for(let n=0;n<3;n++){let x=ix*cell+rand(ix,iy,n)*cell-starX,y=iy*cell+rand(ix+7,iy-2,n)*cell-starY,alt=Math.max(0,-(camera.y+y/z)),alpha=.12+clamp(alt/4000,0,.7);c.globalAlpha=alpha*(.65+.35*Math.sin(time*.3+ix+iy+n));c.fillStyle=n===0?'#c2dcff':'#fff2da';c.beginPath();c.arc(x,y,n===0?1.3:.65,0,Math.PI*2);c.fill();}c.globalAlpha=1;
const gy=(WORLD.ground-camera.y)*z;if(gy<height){let asphalt=c.createLinearGradient(0,gy,0,Math.max(gy+250,height));asphalt.addColorStop(0,'#101d2b');asphalt.addColorStop(1,'#040a13');c.fillStyle=asphalt;c.fillRect(0,Math.max(0,gy),width,height);c.fillStyle='#ad8a4e77';c.fillRect(0,gy, width,2*z);}
if(background){const w=3600,h=w*background.height/background.width,x=(-1000-camera.x*.45)*z,y=(WORLD.ground-.785*h-camera.y)*z;if(y<height&&y+h*z>0)c.drawImage(background,x,y,w*z,h*z);}
// A distant curved atmospheric limb, visible only once the car reaches space.
let space=clamp((-camera.y-13000)/5000,0,1);if(space>0){c.save();c.globalAlpha=space*.7;let y=height+width*.6;c.beginPath();c.arc(width*.5,y,width*.72,Math.PI*1.18,Math.PI*1.82);c.strokeStyle='#235c93';c.lineWidth=9;c.shadowBlur=25;c.shadowColor='#4ba8ec';c.stroke();c.restore();}
}
export function cameraTarget(s,width=1600,height=900){const baseY=(900-height)/2,baseX=(WORLD.w-width)/2;return {x:s.y<0?s.x-width*.5:s.x<baseX+60?s.x-width*.1:s.x>baseX+width-250?s.x-width*.84:baseX,y:Math.min(baseY,s.y-(height<800?height*(s.parachute?.66:.52):(s.parachute?420:310)-baseY)),zoom:1};}
export function updateCamera(camera,s,width,height,dt){const target=cameraTarget(s,width,height);const f=1-Math.exp(-dt*6);camera.x+=(target.x-camera.x)*f;camera.y+=(target.y-camera.y)*f;camera.zoom=1;const screenX=s.x-camera.x;if(screenX<width*.12)camera.x=s.x-width*.12;if(screenX>width*.88)camera.x=s.x-width*.88;const screenY=s.y-camera.y;if(screenY<height*.2)camera.y=s.y-height*.2;if(screenY>height*.7&&s.y<600)camera.y=s.y-height*.7;return camera;}
